DROP PROCEDURE IF EXISTS shop.member_seed;
DELIMITER //
CREATE PROCEDURE shop.member_seed()
BEGIN
  CREATE TABLE IF NOT EXISTS shop.member (
    id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    code VARCHAR(20) NOT NULL,
    name VARCHAR(40) NOT NULL,
    memo VARCHAR(120) NOT NULL DEFAULT '',
    KEY idx_code (code)
  ) ENGINE=InnoDB;
  IF (SELECT COUNT(*) FROM shop.member) = 0 THEN
    INSERT INTO shop.member (code, name, memo)
    SELECT 100000 + (a.id * 1000 + b.id), CONCAT('member-', a.id, '-', b.id), REPEAT('x', 100)
    FROM (SELECT id FROM shop.orders LIMIT 800) a
    JOIN (SELECT id FROM shop.orders LIMIT 1000) b;
  END IF;
END//
DELIMITER ;
CALL shop.member_seed()

ALTER TABLE shop.member MODIFY code VARCHAR(20) NOT NULL;
CREATE TABLE IF NOT EXISTS shop.lookup_log (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, at DATETIME(6) NOT NULL, ms DOUBLE NOT NULL, KEY idx_at (at)) ENGINE=InnoDB;
TRUNCATE TABLE shop.lookup_log;
GRANT SELECT ON mysql.slow_log TO 'dba'@'%';
SET GLOBAL slow_query_log = ON;
SET GLOBAL long_query_time = 1;
TRUNCATE TABLE mysql.slow_log

DROP PROCEDURE IF EXISTS shop.member_lookup;
DELIMITER //
CREATE PROCEDURE shop.member_lookup(n INT) SQL SECURITY INVOKER
BEGIN
  DECLARE i INT DEFAULT 0;
  DECLARE t0 DATETIME(6);
  WHILE i < n DO
    SET t0 = NOW(6);
    SELECT MAX(name) INTO @hit FROM shop.member WHERE code = {{code}};
    INSERT INTO shop.lookup_log (at, ms) VALUES (NOW(6), TIMESTAMPDIFF(MICROSECOND, t0, NOW(6)) / 1000);
    DO SLEEP(0.05);
    SET i = i + 1;
  END WHILE;
END//
DELIMITER ;
GRANT EXECUTE ON shop.* TO 'app'@'%'
